package com.mahoganyhomesnotifier;

import com.google.inject.Provides;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Mahogany Homes Notifier",
	description = "Notifies you if you don't have enough planks or steel bars for a new Mahogany Homes contract",
	tags = {"mahogany", "homes", "construction", "contract", "notification"}
)
public class MahoganyHomesNotifierPlugin extends Plugin
{
	// NPC dialog assigning a new contract, e.g.
	// "Go see Bob in north-east Varrock, opposite the church. You can get another job once you have furnished his home."
	static final Pattern CONTRACT_PATTERN = Pattern.compile("(Please could you g|G)o see (\\w*)[ ,][\\w\\s,-]*[?.] You can get another job once you have furnished \\w* home\\.");

	// NPC dialog reminding the player of their already-active contract, e.g.
	// "You're currently on an Expert Contract. Go see Ross, north of the church in East Ardougne. ..."
	static final Pattern REMINDER_PATTERN = Pattern.compile("You're currently on an? (\\w*) Contract\\. Go see (\\w*)[ ,][\\w\\s,-]*\\. You can get another job once you have furnished \\w* home\\.");

	// Player dialog requesting a contract tier, e.g. "Could I have an Adept contract please?"
	static final Pattern REQUEST_CONTRACT_TIER = Pattern.compile("Could I have an? (\\w*) contract please\\?");

	// Chat message shown when a contract is completed
	static final Pattern CONTRACT_FINISHED = Pattern.compile("You have completed [\\d,]* contracts with a total of [\\d,]* points?\\.");

	private static final int[] PLANK_IDS = {ItemID.WOODPLANK, ItemID.PLANK_OAK, ItemID.PLANK_TEAK, ItemID.PLANK_MAHOGANY};

	@Inject
	private Client client;

	@Inject
	private MahoganyHomesNotifierConfig config;

	@Inject
	private Notifier notifier;

	private RequiredMaterialsByTier currentContact;
	private int contractTier;
	private boolean notifiedForCurrentContract;

	@Provides
	MahoganyHomesNotifierConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MahoganyHomesNotifierConfig.class);
	}

	@Override
	protected void startUp()
	{
		currentContact = null;
		contractTier = 0;
		notifiedForCurrentContract = false;
	}

	@Override
	protected void shutDown()
	{
		currentContact = null;
		contractTier = 0;
		notifiedForCurrentContract = false;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		checkForContractTierDialog();
		checkForAssignmentDialog();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		if (CONTRACT_FINISHED.matcher(Text.removeTags(event.getMessage())).matches())
		{
			currentContact = null;
			contractTier = 0;
			notifiedForCurrentContract = false;
		}
	}

	// Player's own dialog line asking the overseer for a contract tier
	private void checkForContractTierDialog()
	{
		final Widget dialog = client.getWidget(InterfaceID.ChatRight.TEXT);
		if (dialog == null || dialog.getText() == null)
		{
			return;
		}

		final String text = Text.sanitizeMultilineText(dialog.getText());
		final Matcher matcher = REQUEST_CONTRACT_TIER.matcher(text);
		if (matcher.matches())
		{
			setContractTierFromText(matcher.group(1));
		}
	}

	// NPC dialog assigning or reminding the player of a contract
	private void checkForAssignmentDialog()
	{
		final Widget dialog = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (dialog == null || dialog.getText() == null)
		{
			return;
		}

		final String text = Text.sanitizeMultilineText(dialog.getText());

		String name = null;
		Matcher matcher = CONTRACT_PATTERN.matcher(text);
		if (matcher.matches())
		{
			name = matcher.group(2);
		}
		else
		{
			matcher = REMINDER_PATTERN.matcher(text);
			if (matcher.matches())
			{
				name = matcher.group(2);
				setContractTierFromText(matcher.group(1));
			}
		}

		if (name == null)
		{
			return;
		}

		final RequiredMaterialsByTier contact;
		try
		{
			contact = RequiredMaterialsByTier.valueOf(name.trim().toUpperCase());
		}
		catch (IllegalArgumentException e)
		{
			log.debug("Unrecognised Mahogany Homes contact: {}", name);
			return;
		}

		log.debug("Assignment dialog matched: name={} resolvedContact={} tier={}", name, contact, contractTier);

		if (contact != currentContact)
		{
			currentContact = contact;
			notifiedForCurrentContract = false;
		}

		checkMaterials();
	}

	private void setContractTierFromText(final String tierText)
	{
		// The player's own "Could I have an X contract please?" line has a lowercase
		// tier word, while the NPC's "You're currently on an X Contract" reminder has
		// it capitalized - normalize case so both are recognised.
		switch (tierText.toLowerCase())
		{
			case "beginner":
				contractTier = 1;
				break;
			case "novice":
				contractTier = 2;
				break;
			case "adept":
				contractTier = 3;
				break;
			case "expert":
				contractTier = 4;
				break;
			default:
				log.debug("Unrecognised contract tier text: {}", tierText);
				return;
		}

		log.debug("Contract tier set to {} ({})", contractTier, tierText);
		checkMaterials();
	}

	// Checks the assigned contract's material requirements against the player's inventory
	// (including plank sack contents) and fires a single notification if either is short.
	private void checkMaterials()
	{
		if (currentContact == null || contractTier == 0 || notifiedForCurrentContract)
		{
			return;
		}

		final RequiredMaterials required = currentContact.getByTier(contractTier);
		if (required == null)
		{
			return;
		}

		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}

		final int plankId = PLANK_IDS[contractTier - 1];
		int numPlanks = inventory.count(plankId);
		if (inventory.contains(ItemID.PLANK_SACK))
		{
			numPlanks += countPlankSackVarb(plankId);
		}

		final int numSteelBars = inventory.count(ItemID.STEEL_BAR);

		log.debug("Checking materials: contact={} tier={} plankId={} have {} planks (need <= {}), have {} steel bars (need <= {})",
			currentContact, contractTier, plankId, numPlanks, required.MaxPlanks, numSteelBars, required.MaxSteelBars);

		// Only ever evaluate once per assigned contract.
		notifiedForCurrentContract = true;

		if (numPlanks < required.MaxPlanks || numSteelBars < required.MaxSteelBars)
		{
			log.debug("Insufficient materials, notifying");
			notifier.notify(config.insufficientMaterialsNotification(), "You don't have the materials for this contract!");
		}
	}

	private int countPlankSackVarb(final int plankId)
	{
		switch (plankId)
		{
			case ItemID.WOODPLANK:
				return client.getVarbitValue(VarbitID.PLANK_SACK_PLAIN);
			case ItemID.PLANK_OAK:
				return client.getVarbitValue(VarbitID.PLANK_SACK_OAK);
			case ItemID.PLANK_TEAK:
				return client.getVarbitValue(VarbitID.PLANK_SACK_TEAK);
			case ItemID.PLANK_MAHOGANY:
				return client.getVarbitValue(VarbitID.PLANK_SACK_MAHOGANY);
			default:
				return 0;
		}
	}
}

package com.mahoganyhomesnotifier;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;

@ConfigGroup(MahoganyHomesNotifierConfig.GROUP_NAME)
public interface MahoganyHomesNotifierConfig extends Config
{
	String GROUP_NAME = "mahoganyHomesNotifier";

	@ConfigItem(
		keyName = "insufficientMaterialsNotification",
		name = "Insufficient Materials Notification",
		description = "Notifies you when a new Mahogany Homes contract needs more planks or steel bars than you're carrying"
	)
	default Notification insufficientMaterialsNotification()
	{
		return Notification.ON;
	}
}
